    b.teks('Wakaf zaman sekarang',['Katil hospital dan kerusi roda yang dipinjamkan kepada pesakit','Mushaf Al-Quran dan buku ilmu','Telaga dan sistem air','Peralatan masjid, surau dan kelas pengajian'],'Wakaf tidak semestinya besar. Ramai orang boleh berkongsi untuk mewakafkan satu barang, masing-masing mengikut kemampuan.',eyebrow='Contoh')
    b.teks('Wakaf Katil Hospital Muafakat Care',['Keluarga pesakit memohon melalui WhatsApp atau borang.','Sukarelawan menghantar dan memasang katil di rumah pesakit.','Katil dipinjamkan <b>tanpa caj</b> selagi diperlukan.','Apabila tidak lagi digunakan, katil dipulangkan dan disalurkan kepada pesakit seterusnya.'],'<div class="biru"><b>RM50 = 1 slot wakaf.</b> Sumbangan digunakan untuk menambah katil dan menguruskan penghantaran.</div>',eyebrow='Bagaimana ia berjalan')
